#pragma once

#include <QByteArray>
#include <QString>
#include <QVector>

// Field layouts of the Death Knights of Krynn and Pool of Radiance (Amiga)
// records, generated by tools/gen_record_layouts.py from the C ports of the
// two executables (record_layouts_gen.cpp).  All values are big-endian.
namespace RecordLayouts {

struct RecordField
{
    int offset;
    int width;          // 1, 2 or 4 bytes per element
    int count;          // number of elements
    int step;           // distance between elements
    bool isSigned;
    const char *name;
    const char *description;
};

struct RecordLayout
{
    const char *id;     // "dkk.character", "por.item", ...
    const char *title;
    int size;
    const RecordField *fields;
    int fieldCount;
};

extern const RecordLayout layouts[];
extern const int layoutCount;

const RecordLayout *find(const char *id);

struct FieldValue
{
    int offset = 0;
    QString name;
    QString description;
    QString value;
    QString raw;
};

// Values of every field of one record (missing bytes read as empty).
QVector<FieldValue> describe(const RecordLayout &layout, const QByteArray &record);

} // namespace RecordLayouts

// globals.daa of Death Knights of Krynn (load_globals, H006+$069E; decoder
// H032): +$4 offset of the Huffman tree, +$8 offset of the word table, +$C
// the bit stream of $7FEA bytes of the H004 data hunk.
namespace DkkGlobals {

constexpr int imageSize = 0x7FEA;

bool looksLikeGlobals(const QByteArray &file);
QByteArray unpack(const QByteArray &file, QString *error = nullptr);

} // namespace DkkGlobals
